// EXPERIMENT: three station/point arrangements mounted on the settled Map route.
import {cssVars} from './sky-tokens.js';
import {baseStyle} from './station-map.js';
import {normalize,readLive,FOCUSES,TIMES} from './station-data.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={A:'Layer-led',B:'Place roster',C:'Field lens'},descriptions={A:'Select a layer in the stack; its readings and reasons sit below the map.',B:'Start with a place. A roster separates the airport reference from model evidence at the Focus.',C:'Choose a model field at Focus. Its source and sampled grid cell stay visible beside the map.'};
const pretty=s=>String(s??'Unknown').replaceAll('_',' '),stamp=t=>t&&Number.isFinite(Date.parse(t))?new Date(t).toISOString().replace('T',' ').replace(/\.\d{3}Z$/,'Z'):'Not supplied';
const q=new URLSearchParams(location.search);let state={variant:['A','B','C'].includes(q.get('variant'))?q.get('variant'):'A',focus:FOCUSES.find(f=>f.id===q.get('place'))??FOCUSES[0],time:q.get('t')&&Number.isFinite(Date.parse(q.get('t')))?q.get('t'):TIMES[0],mode:'capture',theme:'light',vision:'normal',selection:'awc-metar-speci-surface',reading:null,inspector:false,field:'temperature',stack:[],mapError:null};
if(q.has('lat')&&q.has('lon')&&Number.isFinite(+q.get('lat'))&&Number.isFinite(+q.get('lon'))){const lat=+q.get('lat'),lon=+q.get('lon');if(lat>=45&&lat<=50.5&&lon>=-58&&lon<=-46)state.focus={id:'custom',label:'Chosen map point',lat,lon,coordinateBasis:'User-picked query coordinate; not a reporting station'};}
let capture,T,model,map,markers=[],pending=false,sequence=0,live={requests:{}},mapInitialized=false;
const activeBundle=()=>state.mode==='capture'?capture:state.mode==='live'?live:{requests:{}};
const readable=r=>r.readings.filter(v=>v.valueReadable);
function ageLabel(r){const a=readable(r).map(v=>v.provenance.freshness?.age_seconds);if(!a.length||a.some(x=>!Number.isFinite(x)))return 'Retrieval age unknown';const low=Math.min(...a),high=Math.max(...a);return 'Retrieval age '+(low===high?(high/3600).toFixed(1):((low/3600).toFixed(1)+'–'+(high/3600).toFixed(1)))+' h at API read'}
const selected=()=>model.records.find(r=>r.id===state.selection)??model.records[0];
function sourceColor(id){return `var(--src-${T.palettes.light.C.sources.find(s=>s.sources.includes(id))?.slot??8})`}
function sourceTag(id){return `<span class="source-tag" style="--source-color:${sourceColor(id)}"><span class="source-dot" aria-hidden="true"></span>${esc(id)}</span>`}
function glyph(cls){const c=['retrieved','reprocessed','derived_here','intermediary_derived','generated_display','uncalibrated_observation'].includes(cls)?cls:'unrecognised';return `<svg class="glyph" role="img" aria-label="${esc(c==='unrecognised'?'Evidence class not supplied':pretty(c))}"><use href="#g-${c}"/></svg>`}
const bundleGlyph=r=>glyph(r.evidenceClass.length===1?r.evidenceClass[0]:null),badge=(text,missing=false)=>`<span class="badge ${missing?'missing':''}">${esc(text)}</span>`;
const number=v=>typeof v==='number'?v.toLocaleString('en-CA',{maximumFractionDigits:2}):v==null?'—':String(v);
const unit=u=>({percent:'%',degC:'°C','m s-1':'m/s','kg m-2':'kg/m²'})[u]??u??'';
const numericText=v=>`${number(v.value)} ${unit(v.unit)}`;
function enabled(id){return state.stack.find(s=>s.id===id)?.on??false}
function status(r){if(!enabled(r.id))return 'Hidden from Map';if(r.eligible)return 'Weather marker eligible';if(r.valueReadable)return 'Model evidence · no station marker';return 'Unavailable at Focus'}
function fields(){return model.records.filter(r=>enabled(r.id)&&['surface','upper-air'].includes(r.kind)).flatMap(r=>readable(r).map(v=>({record:r,reading:v})));}
const raw=(name,v)=>`<details><summary>${esc(name)}</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`;
const dl=entries=>`<dl>${entries.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v??'Not supplied')}</dd>`).join('')}</dl>`;
async function init(){
 [T,capture]=await Promise.all(['tokens.json','station-captures.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error(p+' HTTP '+r.status);return r.json()}));
 const glyphMarkup=await(await fetch('station-glyphs.svg')).text();
 document.querySelectorAll('head>style').forEach(el=>el.remove());const css=document.createElement('link');css.rel='stylesheet';css.href='station-study.css';document.head.append(css);const font=document.createElement('link');font.rel='stylesheet';font.href='https://fonts.googleapis.com/css2?'+T.variants.C.fonts.google+'&display=swap';document.head.append(font);document.title='Station and point layers · Map design study';
 document.body.innerHTML=`<a class="skip" href="#s-main">Skip to Map study</a>${glyphMarkup}<div class="study-note"><span>ASTRAEUS / DESIGN STUDY</span><span>Station and point layers · decision pending</span><a href="station-README.md">Study notes</a></div><header class="focusbar"><div><div class="eyebrow">Bench / shared Focus</div><label for="s-focus">Location <select id="s-focus"></select></label></div><div class="appearance"><label for="s-theme">Theme <select id="s-theme"><option value="light">Light</option><option value="dark">Dark</option><option value="night">Red night</option></select></label><label for="s-vision">Vision <select id="s-vision"><option value="normal">Normal</option><option value="gray">Grayscale</option><option value="deutan">Deuteranopia</option></select></label></div></header><div id="s-banner" class="data-banner" role="status"></div><div class="study-shell"><nav class="view-tabs" aria-label="Bench views, shell context"><b aria-current="page">Map</b><span>Series</span><span>Sky</span><span>Activity</span><span>Sources</span></nav><main id="s-main" tabindex="-1"><header class="view-head"><div><div class="eyebrow">Map / non-raster evidence</div><h1 id="s-title"></h1><p id="s-description"></p></div><div class="evidence-controls"><label for="s-mode">Evidence <select id="s-mode"><option value="capture">Historical API capture</option><option value="live">Read live API</option><option value="outage">Unavailable state study</option></select></label><button id="s-read">Read this Focus</button></div></header><div class="map-grid"><aside class="layer-stack" aria-label="Non-raster layer stack"><div class="stack-title"><h2>Layer stack</h2><small>top first</small></div><div id="s-roster"></div><div id="s-stack"></div><div class="layer-row"><p class="reason">This study isolates non-raster layers. The selected Map raster stack remains on the <a id="s-baseline" href="map.html?mv=A">original Map route</a>.</p></div></aside><section class="map-area" aria-label="Map and evidence"><div id="s-variant-context" class="variant-context" hidden></div><div class="map-viewport"><div id="s-map" class="map-canvas" aria-label="Reference map of St. John's"></div><div class="map-toolbar"><button id="s-fit">Fit Focus + CYYT</button><button id="s-airport">Inspect CYYT reports</button></div><section id="s-corner" class="corner" aria-label="Frames and ages"></section><section id="s-lens" class="lens-readout" hidden></section><details class="map-legend" open><summary>Map symbols</summary><p><span class="legend-mark reference"></span>Airport reference only</p><p><span class="legend-mark focus"></span>Shared Focus</p><p><span class="legend-mark observation"></span>Eligible report geometry only</p><p>Reference pins are excluded from weather-marker counts.</p></details><div id="s-map-error" class="map-error" hidden></div></div><div class="disclosure"><span id="s-strip"></span><button id="s-why">Why?</button></div><div id="s-readings" class="reading-panel"></div></section></div><details class="api-notices"><summary id="s-notices-label">API notices and availability</summary><div id="s-notices"></div></details><details class="study-state"><summary>Prototype state and requests</summary><pre id="s-state"></pre></details></main><aside id="s-inspector" class="inspector" aria-label="Docked provenance inspector" hidden><header><span class="eyebrow">Evidence / inspector</span><button id="s-close">Close</button></header><h2 id="s-inspect-title"></h2><div id="s-inspect-body"></div></aside></div><footer class="rail"><label for="s-time">Shared instant <select id="s-time"></select></label><button id="s-now">Use current hour + read live</button><small id="s-local"></small></footer><nav class="switcher" aria-label="Prototype alternatives"><button id="s-prev" aria-label="Previous alternative">←</button><span id="s-variant"></span><button id="s-next" aria-label="Next alternative">→</button></nav>`;
 wire();render();
 if(!window.maplibregl){state.mapError='MapLibre did not load. Evidence remains readable; no substitute map geography is drawn.';showMapError();return;}
 map=new maplibregl.Map({container:'s-map',style:baseStyle(state.theme),center:[-52.72,47.59],zoom:11,attributionControl:{compact:true},fadeDuration:0});
 map.on('load',()=>{mapInitialized=true;drawMarkers();fitMap()});map.on('error',e=>{state.mapError='Reference-map request failed: '+(e.error?.message??'unknown error');showMapError()});
 map.on('click',e=>{if(e.originalEvent?.target?.closest('.reference-pin,.observation-pin,.reference-label'))return;const lat=+e.lngLat.lat.toFixed(4),lon=+e.lngLat.lng.toFixed(4);if(lat<45||lat>50.5||lon< -58||lon> -46){state.mapError='Chosen point is outside the experiment evidence box.';showMapError();return;}state.focus={id:'custom',label:'Chosen map point',lat,lon,coordinateBasis:'User-picked query coordinate; not a reporting station'};if(state.mode==='live')readCurrent();else render()});
}
function renderStack(){
 const byId=Object.fromEntries(model.records.map(r=>[r.id,r]));const picked=selected();const placeGroup=picked.sourceId.startsWith('awc-')?'cyyt':['surface','upper-air'].includes(picked.kind)?'focus':'unplaced';const visibleStack=state.variant==='B'?state.stack.filter(s=>{const r=byId[s.id];return placeGroup==='cyyt'?r.sourceId.startsWith('awc-'):placeGroup==='focus'?['surface','upper-air'].includes(r.kind):!r.sourceId.startsWith('awc-')&&['station','alert'].includes(r.kind)}):state.stack;$('.stack-title h2').textContent=state.variant==='B'?'Places → layers':'Layer stack';$('#s-stack').innerHTML=visibleStack.map(s=>{const i=state.stack.findIndex(x=>x.id===s.id);const r=byId[s.id];return `<section class="layer-row ${state.selection===r.id?'selected':''}"><div class="layer-top"><label><input type="checkbox" data-toggle="${esc(r.id)}" ${s.on?'checked':''} aria-label="Show ${esc(r.label)} in the study"></label><button class="layer-title" data-select="${esc(r.id)}">${bundleGlyph(r)}<span><strong>${esc(r.label)}</strong>${sourceTag(r.sourceId)}</span></button></div>${badge(status(r),!r.eligible&&!r.valueReadable)}<p class="reason">${esc(r.reason)}</p><div class="layer-meta"><span>${r.layer?'Layer advertised':'Layer not served'}</span><span>${r.eligible?'Marker drawn':'No weather marker'}</span></div><div class="order-buttons"><button data-move="${r.id}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(r.label)} up">↑ Up</button><button data-move="${r.id}" data-direction="1" ${i===state.stack.length-1?'disabled':''} aria-label="Move ${esc(r.label)} down">↓ Down</button><button data-inspect="${r.id}">Inspect</button></div></section>`}).join('');
 $('#s-roster').innerHTML=state.variant==='B'?`<section class="place-roster"><h3>Places and evidence</h3><button data-place-roster="cyyt" aria-pressed="${placeGroup==='cyyt'}">CYYT airport<small>Adapter reference location · reports unavailable</small></button><button data-place-roster="focus" aria-pressed="${placeGroup==='focus'}">${esc(state.focus.label)}<small>${fields().length} readable model fields at query · not a station</small></button><button data-place-roster="unplaced" aria-pressed="${placeGroup==='unplaced'}">Not placed<small>AQHI / CAP · no usable returned geometry</small></button></section>`:'';
}
function readingButton(r,v,i){return `<button class="reading" data-reading="${esc(r.id+'|'+i)}"><span class="label">${glyph(v.cls)} ${esc(pretty(v.field))}</span><span class="number">${esc(numericText(v))}</span>${sourceTag(r.sourceId)}<small>${esc(v.provenance.freshness?.status??'Freshness unknown')} · ${esc(v.provenance.vertical_level??'Level not supplied')}</small><small>Valid ${esc(stamp(v.provenance.valid_time))}</small></button>`}
function renderReadings(){
 const r=selected();const values=enabled(r.id)?readable(r):[];$('#s-readings').innerHTML=`<header><h2>${esc(r.label)}</h2><button data-inspect="${r.id}">Full provenance</button></header><p>${esc(r.reason)}</p>${values.length?`<div class="reading-list">${r.readings.map((v,i)=>v.valueReadable?readingButton(r,v,i):'').join('')}</div>`:`<div class="empty">${enabled(r.id)?'— No readable value to show at this Focus. Missing reports do not imply clear sky, good air quality or no alerts.':'Layer is hidden from this study. The inspector retains the response and provenance.'}</div>`}`;
}
function renderCorner(){
 const active=model.records.filter(r=>enabled(r.id));const markers=active.filter(r=>r.eligible&&r.geometry);const rows=active.map(r=>`<button data-inspect="${r.id}"><strong>${esc(r.label)}</strong><br>${r.eligible?'Report '+esc(stamp(r.reportTime)):r.valueReadable?'Model valid '+esc(stamp(r.reportTime)):'No report drawn'}${r.stale?' · retrieval stale':''}${r.valueReadable?'<br>'+esc(ageLabel(r)):''}</button>`);
 $('#s-corner').innerHTML=`<h3>Frames & ages</h3><p>${markers.length} weather markers · ${active.filter(r=>r.valueReadable).length} readable model bundles</p>${rows.slice(0,5).join('')}${rows.length>5?`<details><summary>${rows.length-5} more layers</summary>${rows.slice(5).join('')}</details>`:''}<p>Advertised older samples are not drawn as current reports.</p>`;
 $('#s-strip').textContent=`${markers.length} weather markers / ${active.filter(r=>r.kind==='station'||r.kind==='alert').length} point layers enabled · ${active.filter(r=>r.valueReadable).length} model bundles readable · no generated display`;
}
function renderLens(){
 const choices=[...new Set(fields().map(x=>x.reading.field))];if(!choices.includes(state.field)&&choices.length)state.field=choices.includes('temperature')?'temperature':choices[0];
 const context=$('#s-variant-context');context.hidden=state.variant!=='C';context.innerHTML=`<label for="s-field">Model field at Focus <select id="s-field">${choices.length?choices.map(f=>`<option value="${esc(f)}" ${f===state.field?'selected':''}>${esc(pretty(f))}</option>`).join(''):'<option>No readable model fields</option>'}</select></label><span>Values describe a model sample, never a station report.</span>`;
 const lens=$('#s-lens');lens.hidden=state.variant!=='C';const item=fields().find(x=>x.reading.field===state.field);
 lens.innerHTML=item?`<div class="eyebrow">Model sampled for Focus</div><span class="label">${glyph(item.reading.cls)} ${esc(pretty(item.reading.field))}</span><strong class="number">${esc(numericText(item.reading))}</strong>${sourceTag(item.record.sourceId)}<p>Valid ${esc(stamp(item.reading.provenance.valid_time))}</p><p>Retrieval ${esc(item.reading.provenance.freshness?.status??'unknown')} · grid cell ${esc(item.reading.provenance.sampled_latitude)}, ${esc(item.reading.provenance.sampled_longitude)}</p><p>Cell location is distinct from CYYT and the query point.</p><button data-reading="${item.record.id+'|'+item.record.readings.indexOf(item.reading)}">Inspect sample</button>`:'<div class="eyebrow">Model sampled for Focus</div><strong class="number">—</strong><p>No readable field for this exact coordinate and instant.</p>';
}
function renderInspector(){
 $('#s-inspector').hidden=!state.inspector;$('.study-shell').classList.toggle('inspecting',state.inspector);if(!state.inspector)return;
 const r=selected(),v=state.reading!=null?r.readings[state.reading]:null,p=v?.provenance;
 $('#s-inspect-title').textContent=v?pretty(v.field):r.label;
 $('#s-inspect-body').innerHTML=`<p>${v?glyph(v.cls):bundleGlyph(r)} ${sourceTag(r.sourceId)}</p>${v?`<p class="number">${esc(numericText(v))}</p>`:''}<p>${esc(r.reason)}</p>${dl([['At Focus',stamp(state.time)],['Source',r.sourceId],['Evidence class',v?.cls??(r.evidenceClass.join(', ')||'Not supplied; not inferred')],['Reading kind',r.sourceId==='awc-taf'?'TAF forecast':r.kind==='surface'||r.kind==='upper-air'?'Model sample / derived model field':r.kind],['Weather marker eligible',r.eligible?'Yes':'No'],['Geometry basis',r.geometryBasis],['Reference location',r.referenceGeometry?JSON.stringify(r.referenceGeometry)+' — '+r.referenceGeometryBasis:'None supplied'],['Last advertised sample',stamp(r.lastAdvertisedTime)],['Layer tolerance',r.toleranceSeconds==null?'Not supplied':r.toleranceSeconds+' seconds'],['Advertised sample within layer tolerance',r.withinTolerance?'Yes; does not establish report validity':'No'],['Forecast validity interval',r.validity?JSON.stringify(r.validity):'Not established; cadence is not validity']])}${v?`<h3>Reading provenance</h3>${dl([['Valid time',stamp(p.valid_time)],['Run time',stamp(p.run_time)],['Run stale',p.run_stale==null?'Unknown':String(p.run_stale)],['Run-stale reason',p.run_stale_reason],['Retrieved',stamp(p.retrieval_time)],['Retrieval freshness',p.freshness?.status],['Freshness age at API read',p.freshness?.age_seconds==null?'Not supplied':p.freshness.age_seconds+' seconds'],['Quality',p.quality?.status],['Vertical level',p.vertical_level],['Units',v.unit],['Sampled cell',p.sampled_latitude==null?'Not supplied':`${p.sampled_latitude}, ${p.sampled_longitude}`],['Query coordinate',`${state.focus.lat}, ${state.focus.lon}`],['Sample method',p.sample_method],['Sample distance',p.sample_distance_km==null?'Not supplied':p.sample_distance_km+' km'],['Native resolution',p.native_resolution],['Delivery kind',p.delivery_kind],['Method',p.derivation],['Method version',p.derivation_version],['Citation',p.derivation_citation],['Comparability',v.raw.comparability],['Licence',p.licence],['Attribution',p.attribution]])}${raw('Complete reading, provenance and derivation inputs',v.raw)}`:''}<h3>Response evidence</h3>${raw('Layer, point fields, notices and feature responses',r.raw)}${raw('Point request URL, capture time and complete response',model.pointRequest??{notice:'No exact capture'})}<p>Displayed values are rounded to two decimal places; the complete reading above retains original precision. Independent API reads can see different store states. API-returned numeric zero remains zero; absence stays unavailable.</p>`;
}
function render(){
 model=normalize(activeBundle(),state.focus,state.time);if(!state.stack.length){state.stack=model.records.map(r=>({id:r.id,on:true}));if(q.has('stationStack')){const saved=q.get('stationStack').split(',').map(x=>x.split(':'));const valid=saved.filter(([id])=>model.records.some(r=>r.id===id));if(valid.length===model.records.length&&new Set(valid.map(([id])=>id)).size===valid.length)state.stack=valid.map(([id,on])=>({id,on:on!=='0'}));}}
 for(const[k,v]of Object.entries(cssVars(T,'C',state.theme)))document.documentElement.style.setProperty(k,v);document.documentElement.style.colorScheme=state.theme==='light'?'light':'dark';document.body.dataset.theme=state.theme;document.body.dataset.vision=state.vision;
 $('#s-title').textContent=names[state.variant];$('#s-description').textContent=descriptions[state.variant];$('#s-variant').textContent=state.variant+' · '+names[state.variant];
 $('#s-focus').innerHTML=[...FOCUSES,...(state.focus.id==='custom'?[state.focus]:[])].map(f=>`<option value="${f.id}" ${f.id===state.focus.id?'selected':''}>${esc(f.label)}</option>`).join('');
 $('#s-mode').value=state.mode;$('#s-theme').value=state.theme;$('#s-vision').value=state.vision;$('#s-read').disabled=pending;$('#s-now').disabled=pending;
 const selectedRequests=Object.values(model.requests??{}).filter(r=>r.route==='/layers'||r.route==='/timeline'||(r.route.startsWith('/point?')&&r===model.pointRequest)||r.route.includes(encodeURIComponent(state.time)));const failed=selectedRequests.filter(r=>r.status<200||r.status>=300);
 $('#s-banner').textContent=(pending?'Reading live API…':state.mode==='capture'?'HISTORICAL API CAPTURE · '+stamp(capture.capturedAt):state.mode==='outage'?'UNAVAILABLE STATE STUDY · no evidence':'LIVE READ SESSION · '+stamp(live.capturedAt))+` · ${model.captureMissing?'No exact point response. ':''}${failed.length?failed.length+' selected requests failed. ':''}Reference locations are not reporting stations. Readings retain their own time and source.`;
 const times=[...new Set([...TIMES,state.time].map(t=>new Date(t).toISOString()))].sort();$('#s-time').innerHTML=times.map(t=>`<option value="${t}">${stamp(t)}</option>`).join('');$('#s-time').value=new Date(state.time).toISOString();$('#s-local').textContent=new Date(state.time).toLocaleString('en-CA',{timeZone:'America/St_Johns'})+' · Newfoundland';
 renderStack();renderReadings();renderCorner();renderLens();renderInspector();drawMarkers();showMapError();
 $('#s-notices-label').textContent=`API notices · ${model.notices.length} point notices · report absence is not an all-clear`;
 $('#s-notices').innerHTML=raw('Complete point notices',model.notices)+raw('Layer metadata and capture status',model.layers.map(l=>({id:l.id,kind:l.kind,group:l.group,field:l.field,times:l.times})))+raw('All response statuses',Object.values(model.requests??{}).map(r=>({url:r.url,status:r.status,requestedAt:r.requestedAt,capturedAt:r.capturedAt})));
 updateState();const params=new URLSearchParams({stationStudy:'1',variant:state.variant,place:state.focus.id,t:state.time,mv:'A',view:'map',stationStack:state.stack.map(s=>s.id+':'+(s.on?'1':'0')).join(',')});if(state.focus.id==='custom'){params.set('lat',state.focus.lat);params.set('lon',state.focus.lon)}history.replaceState(null,'','?'+params);$('#s-baseline').href='map.html?mv=A&view=map&t='+encodeURIComponent(state.time)+'&lat='+state.focus.lat+'&lon='+state.focus.lon;
 if(map)requestAnimationFrame(()=>map.resize());
}
function updateState(){$('#s-state').textContent=JSON.stringify({...state,operational:false,mapWeatherMarkers:model.records.filter(r=>r.eligible&&r.geometry&&enabled(r.id)).length,referenceGeometry:'CYYT from checked-in adapter; not a returned report',dataMode:model.dataMode,exactCaptureMissing:model.captureMissing,requests:Object.values(model.requests??{}).map(r=>({route:r.route,status:r.status,requestedAt:r.requestedAt,capturedAt:r.capturedAt}))},null,2)}
function drawMarkers(){
 if(!map||!mapInitialized)return;markers.forEach(m=>m.remove());markers=[];
 const focusPin=document.createElement('div');focusPin.className='focus-pin';focusPin.innerHTML='<span class="reference-label">Shared Focus</span>';markers.push(new maplibregl.Marker({element:focusPin}).setLngLat([state.focus.lon,state.focus.lat]).addTo(map));
 const cyyt=FOCUSES.find(f=>f.id==='cyyt');const airport=document.createElement('button');airport.className='reference-pin';airport.setAttribute('aria-label','CYYT airport reference; inspect report availability');airport.innerHTML=`<span class="reference-label">CYYT · reference only${state.variant==='B'?'<br>METAR / TAF unavailable':''}</span>`;airport.onclick=e=>{e.stopPropagation();state.selection='awc-metar-speci-surface';state.reading=null;state.inspector=true;render();$('#s-inspector').scrollIntoView({block:'nearest'})};markers.push(new maplibregl.Marker({element:airport}).setLngLat([cyyt.lon,cyyt.lat]).addTo(map));
 for(const r of model.records.filter(r=>r.eligible&&r.geometry&&enabled(r.id))){const el=document.createElement('button');el.className='observation-pin';el.setAttribute('aria-label','Inspect '+r.label);el.onclick=e=>{e.stopPropagation();state.selection=r.id;state.inspector=true;state.reading=null;render()};markers.push(new maplibregl.Marker({element:el}).setLngLat(r.geometry).addTo(map));}
}
function showMapError(){const el=$('#s-map-error');if(!el)return;el.hidden=!state.mapError;el.textContent=state.mapError??''}
function fitMap(){if(!map)return;const cyyt=FOCUSES.find(f=>f.id==='cyyt');const bounds=new maplibregl.LngLatBounds([cyyt.lon,cyyt.lat],[state.focus.lon,state.focus.lat]);map.fitBounds(bounds,{padding:{top:100,bottom:100,left:70,right:140},maxZoom:12,duration:0})}
async function readCurrent(){const seq=++sequence;pending=true;state.mode='live';live={requests:{},capturedAt:new Date().toISOString()};render();const b=await readLive({...state.focus},state.time);if(seq!==sequence)return;live=b;pending=false;render()}
function cycle(d){state.variant=['A','B','C'][(['A','B','C'].indexOf(state.variant)+d+3)%3];render();$('#s-stack').scrollTop=0}
function wire(){
 $('#s-prev').onclick=()=>cycle(-1);$('#s-next').onclick=()=>cycle(1);$('#s-focus').onchange=e=>{state.focus=FOCUSES.find(f=>f.id===e.target.value)??state.focus;if(state.mode==='live')readCurrent();else render();fitMap()};$('#s-time').onchange=e=>{state.time=e.target.value;if(state.mode==='live')readCurrent();else render()};
 $('#s-mode').onchange=e=>{state.mode=e.target.value;if(state.mode==='live')readCurrent();else{sequence++;pending=false;render()}};$('#s-read').onclick=readCurrent;$('#s-now').onclick=()=>{const d=new Date();d.setUTCMinutes(0,0,0);state.time=d.toISOString();readCurrent()};
 $('#s-theme').onchange=e=>{state.theme=e.target.value;render();if(map){map.setStyle(baseStyle(state.theme));map.once('style.load',drawMarkers)}};$('#s-vision').onchange=e=>{state.vision=e.target.value;render()};$('#s-fit').onclick=fitMap;$('#s-airport').onclick=()=>{state.selection='awc-metar-speci-surface';state.reading=null;state.inspector=true;render()};$('#s-close').onclick=()=>{state.inspector=false;render();document.querySelector(`[data-inspect="${state.selection}"]`)?.focus()};$('#s-why').onclick=()=>{state.inspector=true;state.reading=null;render()};
 document.addEventListener('click',e=>{const select=e.target.closest('[data-select]'),inspect=e.target.closest('[data-inspect]'),reading=e.target.closest('[data-reading]'),move=e.target.closest('[data-move]'),roster=e.target.closest('[data-place-roster]');if(select||inspect){state.selection=(select??inspect).dataset[select?'select':'inspect'];state.reading=null;if(inspect)state.inspector=true;render()}else if(reading){const[id,i]=reading.dataset.reading.split('|');state.selection=id;state.reading=Number(i);state.inspector=true;render()}else if(move){const i=state.stack.findIndex(s=>s.id===move.dataset.move),j=i+Number(move.dataset.direction);if(j>=0&&j<state.stack.length){[state.stack[i],state.stack[j]]=[state.stack[j],state.stack[i]];render()}}else if(roster){state.selection=roster.dataset.placeRoster==='cyyt'?'awc-metar-speci-surface':roster.dataset.placeRoster==='focus'?'noaa-gfs-surface':'eccc-aqhi-aqhi';state.reading=null;render();$('#s-stack').scrollTop=0}});
 document.addEventListener('change',e=>{if(e.target.dataset.toggle){state.stack.find(s=>s.id===e.target.dataset.toggle).on=e.target.checked;render()}else if(e.target.id==='s-field'){state.field=e.target.value;renderLens();updateState()}});
 document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,button,summary,[contenteditable],.maplibregl-canvas-container'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();cycle(e.key==='ArrowRight'?1:-1)}});
}
init().catch(e=>{document.body.textContent='Station study could not load its assets: '+e.message});
